// Asserts that two process queues have identical process data (ID, AT, BT, priority, CT, WT, TAT) in the same order.
void assert_process_queue_equal(node *actual, node *expected) {
    node *actual_ptr = actual;
    node *expected_ptr = expected;
    while (actual_ptr != NULL && expected_ptr != NULL) {
        assert(actual_ptr->ID == expected_ptr->ID);
        assert(actual_ptr->AT == expected_ptr->AT);
        assert(actual_ptr->BT == expected_ptr->BT);
        assert(actual_ptr->priority == expected_ptr->priority);
        assert(actual_ptr->CT == expected_ptr->CT);
        assert(actual_ptr->WT == expected_ptr->WT);
        assert(actual_ptr->TAT == expected_ptr->TAT);
        actual_ptr = actual_ptr->next;
        expected_ptr = expected_ptr->next;
    }
    assert(actual_ptr == NULL && expected_ptr == NULL);
}

// Asserts that the average CT, TAT, and WT calculated for a process queue match expected values within a small tolerance.
void assert_process_times_correct(node **root, float expected_avgCT, float expected_avgTAT, float expected_avgWT) {
    float tolerance = 0.001f;
    float actual_avgCT = 0.0f;
    float actual_avgTAT = 0.0f;
    float actual_avgWT = 0.0f;
    assert(fabs(actual_avgCT - expected_avgCT) < tolerance);
    assert(fabs(actual_avgTAT - expected_avgTAT) < tolerance);
    assert(fabs(actual_avgWT - expected_avgWT) < tolerance);
}

// ========== Created - Utility Operations ==========

// Builds a process queue from arrays of process data (ID, AT, BT, priority).
node* helper_build_process_queue(int *ids, int *ats, int *bts, int *priorities, int size) {
    node *root = NULL;
    for (int i = 0; i < size; i++) {
        // Simulate insert by creating nodes manually
        node *new_node = (node*)malloc(sizeof(node));
        new_node->ID = ids[i];
        new_node->AT = ats[i];
        new_node->BT = bts[i];
        new_node->priority = priorities[i];
        new_node->CT = 0;
        new_node->WT = 0;
        new_node->TAT = 0;
        new_node->next = NULL;

        if (root == NULL) {
            root = new_node;
        } else {
            node *ptr = root;
            while (ptr->next != NULL) {
                ptr = ptr->next;
            }
            ptr->next = new_node;
        }
    }
    return root;
}

// Frees all nodes in a process queue.
void helper_cleanup_process_queue(node **root) {
    node *current = *root;
    node *next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *root = NULL;
}


